<script setup lang="ts">
import{onMounted,ref}from'vue';import{request}from'../../api/client';import{message}from'../sites/data';const rows=ref<any[]>([]),offset=ref(0),error=ref(''),busy=ref(false);async function load(){rows.value=[];error.value='';busy.value=true;try{rows.value=(await request<any>('/audit?limit=25&offset='+offset.value)).items||[]}catch(e){error.value=message(e)}finally{busy.value=false}}onMounted(load);
</script><template><section><h1>审计记录</h1><p class="muted">受控审计查询仅显示动作、操作者与时间，不显示请求正文或秘密。</p><p v-if="error" role="alert">{{error}}</p><button @click="load" :disabled="busy">刷新审计</button><table><thead><tr><th>时间</th><th>动作</th><th>操作者</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.occurred_at}}</td><td>{{r.action}}</td><td>{{r.actor_id}}</td></tr></tbody></table><button :disabled="busy||!offset" @click="offset-=25;load()">上一页审计</button><button :disabled="busy||rows.length<25" @click="offset+=25;load()">下一页审计</button></section></template>
